using UnityEngine;
namespace CarrotTD {
 /// <summary>
 /// Picks a Mesh LOD level (index ranges generated by the model importer, no extra vertices) for a crowd actor from the CarrotQuality
 /// tier: High keeps light rigs at full detail and drops heavy ones one level, Medium drops one level, Low two. The camera never orbits
 /// close to ordinary mobs, so there is no distance switching and therefore no popping; a tier change re-applies the level.
 /// </summary>
 public sealed class CarrotTierLod : MonoBehaviour {
  public int high,medium=1,low=2;
  Renderer[] renderers;int applied=-1;
  void OnEnable(){if(renderers==null)renderers=GetComponentsInChildren<Renderer>(true);applied=-1;Apply();}
  void LateUpdate(){if(applied!=CarrotQuality.Tier)Apply();}
  void Apply(){
   applied=CarrotQuality.Tier;int level=applied==CarrotQuality.HighTier?high:applied==CarrotQuality.MediumTier?medium:low;
   for(int i=0;i<renderers.Length;i++){var r=renderers[i];if(r!=null)r.forceMeshLod=(short)level;}
  }
  /// <summary>Triangles this actor draws at its current level (QA).</summary>
  public long ActiveTriangles(){
   long total=0;if(renderers==null)return 0;
   foreach(var r in renderers){if(!(r is SkinnedMeshRenderer s)||s.sharedMesh==null)continue;var m=s.sharedMesh;int level=Mathf.Clamp(r.forceMeshLod,0,Mathf.Max(0,m.lodCount-1));
    for(int i=0;i<m.subMeshCount;i++)total+=m.lodCount>1?m.GetLod(i,level).indexCount/3:m.GetIndexCount(i)/3;}
   return total;
  }
 }
}
